def photo_block(url,alt,caption=None):
 return '<figure class="rs-photo">'+photo(url,alt)+('<figcaption>'+e(caption)+'</figcaption>' if caption else '')+'</figure>'
def breadcrumb(title):
 return '<nav class="rs-crumb" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><span>'+e(title)+'</span></nav>'
def hero(title,answer,eyebrow,photo_url,alt,theme='white',caption=None):
 return '<section class="rs-hero rs-hero--'+theme+'"><div class="shell">'+breadcrumb(title)+'<div class="rs-hero__grid"><div class="rs-hero__copy"><span class="eyebrow">'+e(eyebrow)+'</span><h1>'+e(title)+'</h1><p>'+e(answer)+'</p><div class="rs-hero__actions"><a class="button" href="/contact/#inquiry">Discuss a Project →</a><a class="button button--outline" href="/products/">Explore Product Models →</a></div></div>'+photo_block(photo_url,alt,caption)+'</div></div></section>'
def heading(kicker,title,description=''):
 return '<div class="rs-heading"><span class="eyebrow">'+e(kicker)+'</span><h2>'+e(title)+'</h2>'+('<p>'+e(description)+'</p>' if description else '')+'</div>'
def grid_links(items):
 return '<div class="rs-links">'+''.join('<a href="'+e(uri)+'"><span>'+e(name)+'</span><b aria-hidden="true">↗</b></a>' for name,uri in items)+'</div>'
def product_grid():
 return '<div class="rs-products">'+''.join('<a href="'+url+'"><div>'+photo(image,name+' — original XUYI plastic catalog photo')+'</div><strong>'+e(name)+'</strong><span>Explore products ↗</span></a>' for name,url,image in CATALOG)+'</div>'
def question_groups(groups):
 return ''.join('<section class="rs-faq__group" id="'+cat["id"]+'" data-faq-group><header class="rs-faq__group-head"><span class="rs-faq__index">'+cat["icon"]+'</span><div><h2>'+e(cat["name"])+'</h2><p>'+e(cat["summary"])+'</p></div></header><div class="rs-faq__items">'+''.join('<details data-faq-item><summary>'+e(q)+'</summary><div class="rs-faq__answer"><p>'+e(a)+'</p><a href="'+e(link)+'">Related guide or service ↗</a></div></details>' for q,a,link in cat['questions'])+'</div></section>' for cat in groups)
def schema_add(html,key,description,faq_groups=None):
 url='https://xuyi-drinkware-site.pages.dev/'+key+'/'
 org='https://xuyi-drinkware-site.pages.dev/#organization'
 pages=[
  {'@type':'Organization','@id':org,'name':'台州市旭一家居用品有限公司','alternateName':'XUYI Drinkware','url':'https://xuyi-drinkware-site.pages.dev/','address':{'@type':'PostalAddress','addressLocality':'Taizhou','addressRegion':'Zhejiang','addressCountry':'CN'}},
  {'@type':'WebPage','@id':url+'#webpage','url':url,'name':key.replace('-',' ').title()+' | XUYI Drinkware','description':description,'inLanguage':'en','about':{'@id':org}},
  {'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'https://xuyi-drinkware-site.pages.dev/'},{'@type':'ListItem','position':2,'name':key.replace('-',' ').title(),'item':url}]}
 ]
 if faq_groups:
  allq=[(q,a) for c in faq_groups for q,a,_ in c['questions']]
  pages.append({'@type':'FAQPage','@id':url+'#faq','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in allq]})
 script='<script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@graph':pages},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')+'</script>'
 addition='<link rel="stylesheet" href="/assets/resource-pages.css"><script defer src="/assets/resource-pages.js"></script>'+script
 return html.replace('</head>',addition+'</head>',1)
def footer_cta(title,copy):
 return '<section class="rs-footer-cta"><div class="shell"><span class="eyebrow">PLASTIC WATER BOTTLE SOURCING</span><h2>'+e(title)+'</h2><p>'+e(copy)+'</p><a class="button" href="/contact/#inquiry">Prepare a Project Enquiry →</a><small>Preview notice: online submissions remain disabled until contact, privacy and secure delivery details are verified.</small></div></section>'
def faq_page():
 categories=DATA['categories']
